import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>ওয়েবসাইট ধীর হওয়ার সবচেয়ে বড় কারণ প্রায়ই ছবি। বড় ছবি পাতা ভারী করে, আর ব্যবহারকারী অপেক্ষা না করে চলে যায়।</p>\n<p>ওয়েব ইমেজ অপটিমাইজার ছবিকে ওয়েবসাইটের জন্য সঠিক আকারে, সঠিক ফরম্যাটে আর সঠিক মানে তৈরি করে দেয়।</p>\n<p>এই গাইডে আপনি জানবেন প্রিসেট কীভাবে কাজ করে, হিরো ছবি আর পণ্যের ছবি কীভাবে অপটিমাইজ করবেন, আর গতি কীভাবে মাপবেন।</p>\n<h2 id=\"what-is-web-optimisation\">ওয়েব অপটিমাইজেশন কী</h2>\n<p>ওয়েব অপটিমাইজেশন মানে ছবিকে ওয়েবসাইটের জন্য হালকা করা, যাতে পাতা দ্রুত লোড হয়।</p>\n<p>এতে আকার কমানো হয়, ফরম্যাট বদলানো হয়, আর মাপ ঠিক করা হয়। তিনটি একসঙ্গে কাজ করে।</p>\n<p>ভালো অপটিমাইজেশনে ছবি দেখতে ভালো থাকে, আবার পাতাও দ্রুত হয়।</p>\n<h2 id=\"presets-explained\">প্রিসেটগুলো কী বোঝায়</h2>\n<p>প্রিসেট হলো আগে থেকে ঠিক করা সেটিং। হিরো প্রিসেট বড় ছবির জন্য মান বেশি রাখে।</p>\n<p>থাম্বনেইল প্রিসেট ছোট ছবির জন্য আকার ছোট রাখে। মান একটু কম হলেও ছোট দেখালে চোখে পড়ে না।</p>\n<p>পণ্যের প্রিসেট বিবরণ বেশি রাখে। ক্রেতা পণ্যের বিবরণ দেখতে চায়।</p>\n<h2 id=\"hero-images\">হিরো ছবি অপটিমাইজ করা</h2>\n<p>হিরো ছবি পাতার সবচেয়ে বড় ছবি। এটি প্রথমেই লোড হয়, তাই গতি গুরুত্বপূর্ণ।</p>\n<p>হিরো ছবি 200KB-এর নিচে রাখুন। মান ভালো থাকে, পাতাও দ্রুত লোড হয়।</p>\n<p>হিরো ছবির মাপ ঠিক রাখুন। যে মাপে দেখানো হবে, সেই মাপে রাখাই ভালো।</p>\n<h2 id=\"product-images\">পণ্যের ছবি অপটিমাইজ করা</h2>\n<p>পণ্যের ছবিতে ক্রেতা বিবরণ দেখতে চায়। 200KB-তে কাপড়ের বুনন আর পণ্যের প্রান্ত পরিষ্কার দেখায়।</p>\n<p>এক পণ্যের একাধিক ছবি থাকলে প্রতিটি একইভাবে অপটিমাইজ করুন। এতে পাতা গোছানো দেখায়।</p>\n<p>সাদা ব্যাকগ্রাউন্ডের পণ্যের ছবি খুব ভালো কমপ্রেস হয়। ব্যাকগ্রাউন্ডে প্রায় কোনো বাজেট খরচ হয় না।</p>\n<p>পণ্যের ছবিতে সাদা ব্যাকগ্রাউন্ড থাকলে ২০০KB-তে তা পরিষ্কার থাকে। ধূসর দাগ পড়ে না। ক্রেতা পণ্যটিকে পেশাদার মনে করেন।</p>\n<p>পণ্যের ছবিতে রং ঠিক থাকা জরুরি। লাল শাড়ি ২০০KB-তে লালই থাকে, কমলা হয়ে যায় না। কম কোয়ালিটিতে রং বদলে গেলে ক্রেতা ভুল পণ্য পাওয়ার ভয় পান।</p>\n<p>পণ্যের ছবি মোবাইলে দেখা ক্রেতাদের জন্য ২০০KB উপযুক্ত। মোবাইল ডেটায় ছবি দ্রুত আসে, আবার মানও ভালো থাকে। ক্রেতা স্ক্রল করতে করতে ছবি দেখতে পান।</p>\n<p>একই পণ্যের একাধিক কোণ থেকে ছবি থাকলে সবগুলো একই সাইজে অপটিমাইজ করুন। একই মাপের ছবি দোকানের গ্যালারিতে সুন্দর দেখায়।</p>\n<p>পণ্যের ছবির জন্য দিনের আলোয় তোলা ছবি ব্যবহার করুন। ভালো আলোয় তোলা ছবি কম আকারেও পরিষ্কার দেখায়। অন্ধকার ছবি কমপ্রেশনে আরও খারাপ হয়।</p>\n<p>পণ্যের ছবিতে ওয়াটারমার্ক থাকলে তা পড়া যায় এমন আকারে রাখুন। ছোট ফাইলে ওয়াটারমার্কের লেখা ভেঙে যেতে পারে। ব্র্যান্ডের নাম পরিষ্কার রাখুন।</p>\n<p>দোকানের ছবি নিয়মিত আপডেট করুন। পুরোনো ছবির জায়গায় নতুন অপটিমাইজ করা ছবি দিলে দোকান তাজা দেখায়। সার্চ ইঞ্জিনও নতুন ছবিকে ভালো চোখে দেখে।</p>\n<p>পণ্যের ছবিতে জুম করার সুবিধা থাকলে মূল ছবির একটি বড় কপি রাখুন। জুমে দেখানোর জন্য ছোট ফাইল যথেষ্ট নয়। থাম্বনেইল ছোট রাখুন, জুমের ছবি বড় রাখুন।</p>\n<p>পণ্যের ছবির alt টেক্সটে পণ্যের নাম লিখুন। সার্চ ইঞ্জিন ছবি খুঁজে পায়, আর দৃষ্টি প্রতিবন্ধী ক্রেতা ছবিটি বুঝতে পারেন।</p>\n<h2 id=\"cards-thumbnails\">কার্ড ও থাম্বনেইল ছবি</h2>\n<p>কার্ড আর থাম্বনেইল ছোট দেখায়। তাই 100KB-এর নিচে রাখলেই যথেষ্ট।</p>\n<p>এক পাতায় অনেক কার্ড থাকলে প্রতিটি ছবি হালকা রাখুন। মোট ওজন নিয়ন্ত্রণে থাকে।</p>\n<p>থাম্বনেইলের মাপ ঠিক রাখুন। বাড়তি মাপ শুধু ফাইল বড় করে।</p>\n<h2 id=\"copy-img-button\">ছবি কপি করার বোতাম</h2>\n<p>অপটিমাইজার থেকে ছবি কপি করে সরাসরি ব্যবহার করা যায়। HTML কোডও কপি করা যায়।</p>\n<p>HTML কোডে ছবির আকার, alt টেক্সট আর লোডিং সেটিং থাকে। এতে কোড লেখার সময় বাঁচে।</p>\n<p>কোড কপি করার আগে ছবিটি দেখে নিন। মান ঠিক আছে কি না নিশ্চিত করুন।</p>\n<h2 id=\"lazy-loading\">লেজি লোডিং</h2>\n<p>লেজি লোডিং মানে ছবি তখনই লোড হয় যখন ব্যবহারকারী সেখানে স্ক্রল করে।</p>\n<p>এতে পাতা প্রথমে দ্রুত লোড হয়। নিচের ছবিগুলো পরে লোড হয়।</p>\n<p>হিরো ছবিতে লেজি লোডিং ব্যবহার করবেন না। হিরো ছবি প্রথমেই দেখা যায়, তাই তা দ্রুত লোড হওয়া উচিত।</p>\n<p>লেজি লোডিং মানে স্ক্রিনের বাইরের ছবি পরে লোড হয়। পাঠক স্ক্রল করলে ছবি আসে। পাতার প্রথম অংশ দ্রুত দেখা যায়। এটি গতির একটি সহজ কৌশল।</p>\n<p>লেজি লোডিংয়ে loading=\"lazy\" লেখা হয়। ছবির ট্যাগে এই শব্দ যোগ করলে ব্রাউজার ছবি দেরিতে লোড করে। কোডে এক লাইন যোগ করলেই হয়।</p>\n<p>লেজি লোডিং হিরো ছবিতে ব্যবহার করবেন না। হিরো ছবি প্রথমেই দেখা যায়। হিরো ছবিতে লেজি লোডিং দিলে ছবি দেরিতে আসে।</p>\n<p>লেজি লোডিংয়ে ছবির জায়গা আগে থেকে রাখুন। width আর height দিলে ছবি আসার আগে জায়গা থাকে। লেখা সরে যায় না।</p>\n<p>লেজি লোডিং পুরোনো ব্রাউজারে নাও চলতে পারে। নতুন ব্রাউজারে এটি ভালো কাজ করে। পুরোনো ব্রাউজারে ছবি একসঙ্গে লোড হয়।</p>\n<p>লেজি লোডিংয়ে ছবির সংখ্যা বেশি হলে লাভ বেশি। একটি পাতায় বিশটি ছবি থাকলে লেজি লোডিংয়ে পাতা দ্রুত খোলে। দুটি ছবিতে পার্থক্য ধরা পড়ে না।</p>\n<p>লেজি লোডিং পরীক্ষা করতে পাতাটি ধীর ইন্টারনেটে খুলুন। স্ক্রল করলে ছবি আসছে কিনা দেখুন। ছবি না এলে কোডে ভুল আছে।</p>\n<p>লেজি লোডিং আর ছবি কমপ্রেশন একসঙ্গে ব্যবহার করুন। ছোট ছবি আর লেজি লোডিং মিলে পাতা অনেক দ্রুত হয়। দুটি কৌশল একসঙ্গে ভালো কাজ করে।</p>\n<p>লেজি লোডিংয়ে সার্চ ইঞ্জিনের ছবি দেখতে সমস্যা হয় না। গুগল লেজি ছবিও খুঁজে পায়। তবে ছবির alt টেক্সট অবশ্যই দিন।</p>\n<h2 id=\"formats-web\">ওয়েবের জন্য ফরম্যাট</h2>\n<p>ওয়েবসাইটের ছবির জন্য WebP সবচেয়ে ভালো। একই মানের ছবি JPG-এর চেয়ে ছোট হয়।</p>\n<p>পুরোনো ব্রাউজারের জন্য JPG ফলব্যাক রাখুন। এতে সবাই ছবি দেখতে পায়।</p>\n<p>লোগো আর আইকনের জন্য PNG বা SVG ব্যবহার করুন। এতে প্রান্ত তীক্ষ্ণ থাকে।</p>\n<h2 id=\"quality-slider\">কোয়ালিটি স্লাইডার</h2>\n<p>কোয়ালিটি স্লাইডার দিয়ে মান ঠিক করা যায়। বেশি মান মানে পরিষ্কার ছবি, তবে বড় ফাইল।</p>\n<p>ওয়েবসাইটের ছবির জন্য 75 থেকে 85 ভালো। এতে ছবি পরিষ্কার থাকে আর ফাইলও হালকা থাকে।</p>\n<p>স্লাইডার বদলে ফল দেখুন। যে মানে ছবি ভালো দেখায় সেটি বেছে নিন।</p>\n<h2 id=\"exif-stripping\">EXIF ডেটা সরানো</h2>\n<p>ছবিতে EXIF ডেটা থাকে, যেমন ক্যামেরার তথ্য আর GPS অবস্থান। এটি ফাইল বড় করে।</p>\n<p>অপটিমাইজার EXIF ডেটা সরিয়ে দেয়। এতে ফাইল ছোট হয় আর গোপনীয়তাও রক্ষা হয়।</p>\n<p>ছবি শেয়ার করার আগে EXIF সরানো ভালো। এতে অবস্থানের তথ্য ফাঁস হয় না।</p>\n<p>EXIF তথ্য মুছে ফেললে ছবির অবস্থান আর তারিখের তথ্য যায়। ব্যক্তিগত ছবি শেয়ার করার আগে EXIF মুছে ফেলা নিরাপদ। অবস্থানের তথ্য অপরিচিত মানুষের হাতে যাওয়া উচিত নয়।</p>\n<p>ওয়েবের ছবি থেকে EXIF তথ্য মুছে ফেললে ছবির মান বদলায় না। শুধু ক্যামেরা আর অবস্থানের তথ্য যায়, ছবি যেমন আছে তেমন থাকে।</p>\n<p>EXIF তথ্য মুছে ফেলতে টুলের সেটিংয়ে অপশন থাকে। অপশনটি চালু করলে ছবি থেকে সব তথ্য মুছে যায়। অপশনটি বন্ধ থাকলে তথ্য থেকে যায়।</p>\n<p>ওয়েবের ছবি আর্কাইভ করতে হলে EXIF তথ্য রেখে দিন। তারিখ আর ক্যামেরার তথ্য পরে কাজে লাগে, তাই আর্কাইভের কপিতে EXIF রাখুন।</p>\n<p>EXIF তথ্য মুছে ফেলার আগে ভাবুন তথ্য দরকার কিনা। ফটোগ্রাফারদের জন্য ক্যামেরার সেটিংয়ের তথ্য গুরুত্বপূর্ণ। সাধারণ শেয়ারে তথ্য দরকার নেই।</p>\n<p>ওয়েবে EXIF মুছে ফেলার পরও ছবির অরিয়েন্টেশন ঠিক থাকে। টুল অরিয়েন্টেশনের তথ্য পড়ে ছবি সোজা করে, তারপর তথ্য মুছে দেয়।</p>\n<p>EXIF তথ্য মুছে ফেললে ফাইল একটু ছোট হয়। তথ্যের আকার সামান্য। তবে হাজারটি ছবিতে সঞ্চয় ধরা পড়ে।</p>\n<p>ওয়েবে EXIF মুছে ফেলার নিয়ম দলের সবাইকে জানান। ক্লায়েন্টের ছবিতে EXIF থাকা উচিত নয়, তাই নিয়মটা লিখে রাখুন।</p>\n<p>EXIF তথ্য পরীক্ষা করতে ছবির প্রোপার্টি দেখুন। প্রোপার্টিতে তারিখ আর অবস্থান লেখা থাকে, আর তথ্য থাকলে মুছে ফেলুন।</p>\n<h2 id=\"batch-web\">ওয়েবের জন্য ব্যাচ করা</h2>\n<p>ওয়েবসাইটের অনেক ছবি একসঙ্গে করতে ব্যাচ টুল ব্যবহার করুন। একই প্রিসেটে সব ছবি একই মানে তৈরি হয়।</p>\n<p>ব্যাচের আগে একটি ছবি পরীক্ষা করুন। প্রিসেট ঠিক থাকলে বাকিগুলোও ভালো হবে।</p>\n<p>ব্যাচ শেষে প্রতিটি ছবি দেখুন। কোনো ছবি খারাপ লাগলে আলাদাভাবে আবার করুন।</p>\n<h2 id=\"og-images\">OG ছবি অপটিমাইজ করা</h2>\n<p>OG ছবি সোশ্যাল মিডিয়ায় শেয়ার করার সময় দেখায়। এটি 1200 বাই 630 পিক্সেল হওয়া উচিত।</p>\n<p>OG ছবি 200KB-এর নিচে রাখুন। এতে শেয়ার দ্রুত লোড হয়।</p>\n<p>OG ছবিতে লেখা বড় রাখুন। ছোট লেখা শেয়ারে পড়া যায় না।</p>\n<h2 id=\"retina-web\">রেটিনা পর্দায় ছবি</h2>\n<p>রেটিনা পর্দায় পিক্সেল ঘন থাকে, তাই ছবি একটু নরম দেখাতে পারে।</p>\n<p>বড় ছবির জন্য রেটিনা পর্দায় 200KB ভালো। দ্বিগুণ ঘনত্বে দেখালে বেশি বিবরণ দরকার হয়।</p>\n<p>সব ছবি রেটিনার জন্য বড় করবেন না। এতে পাতা ভারী হয়।</p>\n<p>CDN মানে ছবি ব্যবহারকারীর কাছাকাছি সার্ভার থেকে আসে। দূরের সার্ভার থেকে ছবি আসতে সময় লাগে। কাছের সার্ভার থেকে ছবি দ্রুত আসে।</p>\n<p>CDN ব্যবহার করলে পাতা দ্রুত লোড হয়। ছবি কাছের সার্ভার থেকে আসে। দর্শক অপেক্ষা না করে ছবি দেখতে পান।</p>\n<p>CDN-এ ছবি ক্যাশে থাকে। একবার লোড হওয়া ছবি আবার লোড করতে হয় না। দ্বিতীয়বার পাতা আরও দ্রুত খোলে।</p>\n<p>CDN ব্যবহার করার সময় ছবির URL বদলে যায়। নতুন URL-এ ছবি থাকে। পুরোনো URL-এ ছবি নাও থাকতে পারে। লিংক আপডেট করুন।</p>\n<p>CDN-এ ছবি আপলোড করার পর তা পরীক্ষা করুন। ছবি ঠিকমতো দেখা যাচ্ছে কিনা দেখুন। ছবি না দেখা গেলে CDN-এর সেটিং দেখুন।</p>\n<p>CDN ব্যবহার করলে ছবির আকার ছোট রাখা আরও জরুরি। CDN ছোট ছবি দ্রুত দেয়। বড় ছবি CDN-এও ধীর হয়।</p>\n<p>CDN-এর খরচ ছবির সংখ্যা আর আকারের উপর নির্ভর করে। ছোট ছবিতে খরচ কম হয়। বড় ছবিতে খরচ বেশি হয়।</p>\n<p>CDN ব্যবহার করার সময় ছবির ক্যাশের সময় ঠিক করুন। ক্যাশের সময় বেশি হলে ছবি আপডেট হতে দেরি হয়। নতুন ছবিতে ক্যাশ পরিষ্কার করুন।</p>\n<p>CDN আর ছবি কমপ্রেশন একসঙ্গে ব্যবহার করুন। ছোট ছবি আর CDN মিলে পাতা অনেক দ্রুত হয়। দুটি কৌশল একসঙ্গে ভালো কাজ করে।</p>\n<h2 id=\"alt-text-web\">Alt টেক্সট লেখা</h2>\n<p>প্রতিটি ছবিতে alt টেক্সট যোগ করুন। এটি SEO-তে সাহায্য করে আর স্ক্রিন রিডার ব্যবহারকারীদের কাজে লাগে।</p>\n<p>Alt টেক্সটে ছবিটি কী দেখায় তা সংক্ষেপে লিখুন। কীওয়ার্ড ভরবেন না।</p>\n<p>সাজানোর ছবিতে alt টেক্সট খালি রাখুন। এতে স্ক্রিন রিডার সেগুলো এড়িয়ে যায়।</p>\n<h2 id=\"cdn-caching\">CDN আর ক্যাশিং</h2>\n<p>CDN ছবি ব্যবহারকারীর কাছাকাছি সার্ভার থেকে দেয়। এতে লোড দ্রুত হয়।</p>\n<p>ক্যাশিং মানে ব্রাউজার ছবি সংরক্ষণ করে। পরের বার পাতা খুললে ছবি দ্রুত লোড হয়।</p>\n<p>ছবির নাম বদলালে ক্যাশ আপডেট হয়। নতুন ছবিতে নতুন নাম ব্যবহার করুন।</p>\n<h2 id=\"webp-fallback\">WebP ফলব্যাক</h2>\n<p>WebP আধুনিক ব্রাউজারে চলে, তবে পুরোনো ব্রাউজারে নাও চলতে পারে।</p>\n<p>ফলব্যাক মানে WebP না চললে JPG দেখানো। এতে সবাই ছবি দেখতে পায়।</p>\n<p>HTML-এ picture ট্যাগ দিয়ে ফলব্যাক দেওয়া যায়। প্রথমে WebP, তারপর JPG লিখুন।</p>\n<h2 id=\"measuring-web\">গতি মাপা</h2>\n<p>অপটিমাইজের আগে আর পরে পাতার গতি পরীক্ষা করুন। PageSpeed Insights ব্যবহার করুন।</p>\n<p>ছবির মোট ওজন দেখুন। এক মেগাবাইটের নিচে রাখার চেষ্টা করুন।</p>\n<p>মাসে একবার পুরোনো ছবির ওজন পরীক্ষা করুন। বড় ছবি পেলে অপটিমাইজ করে নিন।</p>\n<p>ওয়েবসাইটের গতি বাড়াতে <a href=\"/bn/web-image-optimizer\">ওয়েব ইমেজ অপটিমাইজার</a> ব্যবহার করুন, আর ধাপে ধাপে পদ্ধতির জন্য দেখুন <a href=\"/bn/blog/website-speed-er-jonno-image-optimize-kivabe-korben\">ওয়েবসাইটের গতির জন্য ছবি অপটিমাইজ করবেন কীভাবে</a>। Core Web Vitals জানতে পড়ুন <a href=\"/bn/blog/image-optimization-core-web-vitals\">ছবি অপটিমাইজেশন ও Core Web Vitals</a>। বড় ছবির জন্য <a href=\"/bn/image-200kb-te-compress-korun\">200KB কমপ্রেসর</a> দেখুন।</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ওয়েব ইমেজ অপটিমাইজার কী?","answer":"এটি একটি টুল, যা ছবিকে ওয়েবসাইটের জন্য হালকা করে। আকার কমায়, ফরম্যাট বদলায় আর মাপ ঠিক করে। এতে পাতা দ্রুত লোড হয়, আবার ছবিও পরিষ্কার থাকে।"},{"question":"হিরো ছবি কত বড় রাখা উচিত?","answer":"200KB-এর নিচে রাখুন। হিরো ছবি পাতার সবচেয়ে বড় ছবি, তাই মান গুরুত্বপূর্ণ। তবে 200KB-এর বেশি হলে পাতা ধীর হয়। মাপ ঠিক রাখুন, যে মাপে দেখানো হবে সেই মাপে রাখুন।"},{"question":"WebP কি ওয়েবসাইটের জন্য ভালো?","answer":"হ্যাঁ, খুব ভালো। WebP একই মানের ছবি JPG-এর চেয়ে ছোট হয়। তবে পুরোনো ব্রাউজারের জন্য JPG ফলব্যাক রাখুন, যাতে সবাই ছবি দেখতে পায়।"},{"question":"লেজি লোডিং কী?","answer":"লেজি লোডিং মানে ছবি তখনই লোড হয় যখন ব্যবহারকারী সেখানে স্ক্রল করে। এতে পাতা প্রথমে দ্রুত লোড হয়। তবে হিরো ছবিতে লেজি লোডিং ব্যবহার করবেন না, কারণ তা প্রথমেই দেখা যায়।"},{"question":"EXIF ডেটা সরানো কেন জরুরি?","answer":"EXIF ডেটায় ক্যামেরার তথ্য আর GPS অবস্থান থাকে। এটি ফাইল বড় করে আর গোপনীয়তার ঝুঁকি তৈরি করে। অপটিমাইজার EXIF সরিয়ে দেয়, এতে ফাইল ছোট হয় আর অবস্থানের তথ্য ফাঁস হয় না।"},{"question":"ওয়েবসাইটের গতি কীভাবে মাপব?","answer":"PageSpeed Insights দিয়ে পাতার গতি পরীক্ষা করুন। অপটিমাইজের আগে আর পরে তুলনা করুন। ছবির মোট ওজন এক মেগাবাইটের নিচে রাখার চেষ্টা করুন।"}];
